// Parse the dashboard's publish request.
const input = $input.first().json;
let body = (input && input.body !== undefined) ? input.body : input;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
body = body || {};
return [{ json: {
  job_id: (body.job_id || '').toString(),
  title: (body.title || '').toString(),
  slug: (body.slug || '').toString(),
  author: (body.author || '').toString(),
  category: (body.category || '').toString(),
  reading_time: Number(body.reading_time) || 5,
  excerpt: (body.excerpt || '').toString(),
  cover_alt: (body.cover_alt || '').toString(),
  meta_title: (body.meta_title || '').toString(),
  meta_description: (body.meta_description || '').toString()
} }];

// Convert markdown draft -> Portable Text and attach cover image as binary.
const job = $('Get Job').first().json;
const md = job.draft_md || '';
const newKey = () => '_k' + Math.random().toString(36).slice(2, 10);
const span = (text) => ({ _type: 'span', _key: newKey(), text, marks: [] });
const blk = (style, text) => ({ _type: 'block', _key: newKey(), style, markDefs: [], children: [span(text)] });
const li = (level, text, ordered) => ({ _type: 'block', _key: newKey(), style: 'normal', listItem: ordered ? 'number' : 'bullet', level, markDefs: [], children: [span(text)] });
const blocks = [];
const lines = md.split('\n');
let i = 0;
while (i < lines.length) {
  const trimmed = (lines[i] || '').trim();
  if (!trimmed) { i++; continue; }
  let m;
  if ((m = trimmed.match(/^(#{1,4})\s+(.+)$/))) {
    blocks.push(blk('h' + m[1].length, m[2].trim()));
  } else if ((m = trimmed.match(/^[-*+]\s+(.+)$/))) {
    blocks.push(li(1, m[1].trim(), false));
  } else if ((m = trimmed.match(/^\d+\.\s+(.+)$/))) {
    blocks.push(li(1, m[1].trim(), true));
  } else {
    let para = trimmed;
    while (i + 1 < lines.length) {
      const next = (lines[i + 1] || '').trim();
      if (!next || /^#{1,4}\s/.test(next) || /^[-*+]\s/.test(next) || /^\d+\.\s/.test(next)) break;
      i++;
      para += ' ' + next;
    }
    blocks.push(blk('normal', para));
  }
  i++;
}
const mime = job.mime_type || 'image/png';
const ext = /jpeg|jpg/i.test(mime) ? 'jpg' : /webp/i.test(mime) ? 'webp' : 'png';
const item = { json: { body: blocks, has_image: !!job.image_b64 } };
if (job.image_b64) {
  const buf = Buffer.from(job.image_b64, 'base64');
  item.binary = { cover: await this.helpers.prepareBinaryData(buf, 'cover.' + ext, mime) };
}
return [item];

// Build the Sanity mutation payload: createIfNotExists author + category
// (idempotent, keyed by slugified name), then create the post itself.
const fields = $('Parse Webhook Input').first().json;
const body = $('Convert Markdown to PT').first().json.body;
const uploadResult = $input.first().json;
const assetId = (uploadResult && uploadResult.document && uploadResult.document._id) || '';
const slugify = (s) => (s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'item';
const authorSlug = slugify(fields.author);
const categorySlug = slugify(fields.category);
const mutations = [
  { createIfNotExists: { _id: 'author-' + authorSlug, _type: 'author', name: fields.author || 'Unknown' } },
  { createIfNotExists: { _id: 'category-' + categorySlug, _type: 'category', title: fields.category || 'Uncategorized' } },
  { create: {
    _type: 'post',
    title: fields.title,
    slug: { _type: 'slug', current: fields.slug || slugify(fields.title) },
    author: { _type: 'reference', _ref: 'author-' + authorSlug },
    category: { _type: 'reference', _ref: 'category-' + categorySlug },
    readingTime: Number(fields.reading_time) || 5,
    excerpt: fields.excerpt || '',
    coverImage: assetId ? { _type: 'image', asset: { _type: 'reference', _ref: assetId }, alt: fields.cover_alt || '' } : undefined,
    body,
    metaTitle: fields.meta_title || '',
    metaDescription: fields.meta_description || '',
    publishedAt: new Date().toISOString()
  } }
];
return [{ json: { mutations } }];
